for (const item of items) {
  const body = item.json.body || item.json;
  const d = body;

  const sessionId = item.json.sessionId || `session-${d.sessionDate || new Date().toISOString().split('T')[0]}-${Date.now()}`;

  const esc = (s) => (s || '').replace(/\"/g, '\\"');

  // ── Narrative programs section ──────────────────────────────
  let programsProse = '';
  const progList = Array.isArray(d.programs) && d.programs.length > 0 ? d.programs : [];
  if (progList.length > 0) {
    programsProse = 'During this session, the following skill acquisition programs were targeted. ';
    progList.forEach((p, i) => {
      const skill = p.skill || 'a skill';
      const prog = p.program || 'a program';
      const indep = p.independence ?? 'N/A';
      const trials = p.totalTrials ?? 0;
      const prompt = p.promptType ? `with ${p.promptType.toLowerCase()} prompting` : 'with minimal prompting';
      programsProse += `For the ${prog} program targeting ${skill}, the client achieved ${indep}% independence across ${trials} trials ${prompt}. `;
    });
  } else {
    programsProse = 'No specific skill acquisition programs were targeted during this session. ';
  }

  // ── Narrative behaviors section ─────────────────────────────
  let behaviorsProse = '';
  const behList = Array.isArray(d.targetBehaviors) && d.targetBehaviors.length > 0 ? d.targetBehaviors : [];
  if (behList.length > 0) {
    behaviorsProse = 'In terms of behavior reduction, ';
    behList.forEach((b, i) => {
      const behavior = b.behavior || 'a target behavior';
      const instances = b.instances ?? 0;
      const antecedent = b.antecedent ? ` Antecedent: ${b.antecedent}.` : '';
      const intervention = b.interventionUsed ? ` The intervention implemented was ${b.interventionUsed}.` : '';
      const outcome = b.outcome ? `${b.outcome} - ${b.outcomeDescription || ''}` : 'the outcome was positive';
      behaviorsProse += `${behavior} occurred ${instances} time(s).${antecedent}${intervention} The outcome was ${outcome}. `;
    });
  } else {
    behaviorsProse = 'No maladaptive behaviors were observed during the session. ';
  }

  // ── Narrative transitions ───────────────────────────────────
  const transRating = d.transitionsRating || 'moderate';
  const transProse = d.transitionsDescription
    ? `Transitions were ${transRating} — ${d.transitionsDescription}`
    : `Transitions were ${transRating}`;

  // ── Environment ─────────────────────────────────────────────
  const envProse = d.environmentChanges && d.environmentChanges.toLowerCase() !== 'none'
    ? `Regarding environmental factors, ${d.environmentChanges}.`
    : 'No significant environmental changes were reported.';

  // ── Parent comm ─────────────────────────────────────────────
  const parentProse = d.parentCommunicationProvided
    ? 'Parent or caregiver communication was provided following the session.'
    : `Parent or caregiver communication was not provided${d.parentCommunicationReason ? ' because ' + d.parentCommunicationReason : '.'}`;

  // ── Focus areas ─────────────────────────────────────────────
  const focusProse = d.focusAreas
    ? `The plan for the next session will continue current programs with a focus on ${d.focusAreas}.`
    : 'The plan for the next session is to continue current programs.';

  // ── Narrative draft ────────────────────────────────────────
  const narrativeDraft = `Session Summary
A therapy session was conducted on ${d.sessionDate || 'the scheduled date'} at ${d.location || 'the usual setting'} from ${d.sessionTime || 'the scheduled time'}. The session was staffed by ${d.rbtName || 'the RBT'}, with ${d.participants || 'the client and therapist'} participating. The client was present for the full duration, and services were delivered on a one-to-one basis.

${transProse}. ${envProse}

${programsProse}

${behaviorsProse}

${parentProse}

${focusProse}`;

  // ── Programs JSON for structured output ─────────────────────
  const programsJson = progList.length > 0
    ? JSON.stringify(progList.map((p, i) => ({number: i + 1, skill: p.skill || 'N/A', program: p.program || 'N/A', independence: (p.independence ?? 'N/A') + '%', trials: p.totalTrials ?? 0, prompt_type: p.promptType || 'none'})))
    : '[{"number": 1, "skill": "N/A", "program": "N/A", "independence": "0%", "trials": 0, "prompt_type": "none"}]';

  const behaviorsJson = behList.length > 0
    ? JSON.stringify(behList.map((b, i) => ({number: i + 1, behavior: b.behavior || 'N/A', data: b.instances ?? 0, antecedent: b.antecedent || 'N/A', intervention: b.interventionUsed || 'N/A', outcome: b.outcome || 'Positive', outcome_description: b.outcomeDescription || ''})))
    : '[{"number": 1, "behavior": "N/A", "data": 0, "antecedent": "N/A", "intervention": "N/A", "outcome": "Positive", "outcome_description": ""}]';

  const parentReasonJson = (!d.parentCommunicationProvided && d.parentCommunicationReason)
    ? '"' + esc(d.parentCommunicationReason) + '"'
    : 'null';

  // ── Prompt ──────────────────────────────────────────────────
  const prompt = `You are a BACB-certified clinical supervisor assistant. Below is a rough draft of an ABA session note written in narrative style. Polish it into a professional, BACB-compliant clinical note that reads as a cohesive clinical narrative. Do not over-extend, be clear and concise.

=== DRAFT SESSION NOTE ===
${narrativeDraft}

=== INSTRUCTIONS ===
- Rewrite the note as a flowing clinical narrative — NOT a list, NOT a form with labels.
- Use complete sentences and paragraphs. Avoid bullet points, labeled sections, and structured formatting.
- Maintain professional, objective, and clinically precise language throughout.
- The note should read like a therapist writing a progress summary — seamless and prose-like.
- Incorporate BACB Ethics Code references naturally into the narrative where relevant.
- Do NOT invent data that was not provided.
- The rendered_note field must contain the COMPLETE polished narrative as a single block of prose text.
- Return ONLY raw JSON, no markdown, no code fences, no explanations.

=== OUTPUT FORMAT ===
{
  "id": "<UUID v4>",
  "session_date": "${esc(d.sessionDate)}",
  "rbt_name": "${esc(d.rbtName)}",
  "location": "${esc(d.location)}",
  "session_time": "${esc(d.sessionTime)}",
  "participants": "${esc(d.participants)}",
  "transitions_rating": "${transRating.toLowerCase()}",
  "transitions_description": "<polished narrative>",
  "environment_changes": "<polished narrative>",
  "rendered_note": "<COMPLETE POLISHED NARRATIVE NOTE as flowing prose — NO bullet points, NO labels, NO structured sections>",
  "programs": ${programsJson},
  "target_behaviors": ${behaviorsJson},
  "parent_communication_provided": ${d.parentCommunicationProvided ? 'true' : 'false'},
  "parent_communication_reason": ${parentReasonJson},
  "plan_continue_current": true,
  "plan_focus_areas": "${esc(d.focusAreas)}",
  "bacb_references": [
    {"code": "<BACB code>", "title": "<code title>", "application": "<how applied in this session>"}
  ],
  "recommendations": ["<rec 1>", "<rec 2>"],
  "created_at": "<ISO 8601 timestamp>"
}

Rules:
- rendered_note must be a flowing narrative — no bullet points, no colon-separated labels, no structured sections.
- Include at least 3 BACB code references with specific applications.
- Response must be raw JSON only.`;

  item.json.chatInput = prompt;
  item.json.sessionId = sessionId;
}
return items;

for (const item of items) {
  const content = item.json.output;
  if (typeof content === 'string') {
    const cleanContent = content
      .replace(/^```(?:json)?\s*/m, '')
      .replace(/\s*```$/m, '')
      .trim();
    try {
      const parsed = JSON.parse(cleanContent);

      for (const key of ['programs', 'target_behaviors', 'bacb_references', 'recommendations']) {
        if (parsed[key] && typeof parsed[key] === 'object') {
          parsed[key] = JSON.stringify(parsed[key]);
        }
      }

      if (!parsed.session_date || parsed.session_date.trim() === '') {
        const now = new Date();
        const y = now.getFullYear();
        const m = String(now.getMonth() + 1).padStart(2, '0');
        const d = String(now.getDate()).padStart(2, '0');
        parsed.session_date = `${y}-${m}-${d}`;
      }

      const structured = {
        location: parsed.location,
        session_time: parsed.session_time,
        participants: parsed.participants,
        transitions_rating: parsed.transitions_rating,
        transitions_description: parsed.transitions_description,
        environment_changes: parsed.environment_changes,
        programs: parsed.programs ? JSON.parse(parsed.programs) : [],
        target_behaviors: parsed.target_behaviors ? JSON.parse(parsed.target_behaviors) : [],
        parent_communication_provided: parsed.parent_communication_provided,
        parent_communication_reason: parsed.parent_communication_reason,
        plan_continue_current: parsed.plan_continue_current,
        plan_focus_areas: parsed.plan_focus_areas,
        recommendations: parsed.recommendations ? JSON.parse(parsed.recommendations) : []
      };
      parsed.structured_data = JSON.stringify(structured);

      item.json = parsed;
    } catch(e) {
      item.json = {
        error: "Failed to parse session note JSON: " + e.message,
        raw_output: content.substring(0, 500)
      };
    }
  }
}
return items;

